import json
with open('/private/tmp/claude-501/-Users-taha/c7a33960-1c96-4b0c-b15f-02a996414e54/scratchpad/liquidglass.json') as f:
    d = json.load(f)

def extract_text(node, out):
    if isinstance(node, dict):
        if node.get('type') == 'text' and 'text' in node:
            out.append(node['text'])
        elif node.get('type') == 'codeVoice' and 'code' in node:
            out.append(node['code'])
        for k,v in node.items():
            if k not in ('text','code'):
                extract_text(v, out)
    elif isinstance(node, list):
        for item in node:
            extract_text(item, out)

out = []
extract_text(d.get('abstract', []), out)
print('ABSTRACT:', ''.join(out))
print()

# primary content sections
for sec in d.get('primaryContentSections', []):
    if sec.get('kind') == 'content':
        for block in sec.get('content', []):
            btype = block.get('type')
            if btype in ('paragraph','heading'):
                out = []
                extract_text(block.get('inlineContent', []), out)
                text = ''.join(out)
                if btype == 'heading':
                    print()
                    print('##', text)
                else:
                    print(text)
            elif btype == 'unorderedList':
                for item in block.get('items', []):
                    for c in item.get('content', []):
                        out = []
                        extract_text(c.get('inlineContent', []), out)
                        print('  -', ''.join(out))
"

